"use client";

/**
 * Headline reveal: one headline arrives four ways. Words rise out of a soft
 * blur, letters land one by one while the tracking settles, words build the
 * line from the centre, or words fly in out of order and lock into place.
 *
 * Written by Better Design. Painted from the theme prop, so the headline takes
 * the product's ink and the moving parts take its primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import type { ReactNode } from "react";
import { AbsoluteFill, interpolate, random, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, springs, type VideoTheme, useVideoTheme } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["600", "700"], subsets: ["latin"] });

/** How the headline arrives. */
export type HeadlineRevealVariant = "words" | "letters" | "build" | "gather";

export interface HeadlineRevealProps {
  /** The headline. Keep it to one or two lines. */
  text?: string;
  /**
   * `words` rise out of a blur, `letters` land one by one as the tracking
   * settles, `build` adds words one at a time from the centre, `gather` flies
   * words in out of order and locks them into the sentence.
   */
  variant?: HeadlineRevealVariant;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const TRACK = -0.035;

/** Bring a headline on screen with one of four entrances. */
export function HeadlineReveal({
  text = "Every launch deserves a film",
  variant = "words",
  theme: themeOverride,
  font,
}: HeadlineRevealProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);
  const words = text.split(/\s+/).filter(Boolean);
  // Build keeps the line on one row, so its size follows the length.
  const size = variant === "build" ? Math.min(132, Math.round(1640 / Math.max(1, text.length * 0.48))) : 132;

  const base = {
    fontSize: size,
    fontWeight: 700,
    lineHeight: 1.04,
    color: theme.foreground,
    letterSpacing: `${TRACK}em`,
  } as const;

  let body: ReactNode;

  if (variant === "letters") {
    const offsets = words.map((_, wi) => words.slice(0, wi).join(" ").length + (wi > 0 ? 1 : 0));
    const track = interpolate(easings.out(progress(frame, 0, 52)), [0, 1], [0.22, TRACK]);
    body = (
      <h1 style={{ ...base, margin: 0, letterSpacing: `${track}em`, textAlign: "center", maxWidth: 1560, textWrap: "balance" }}>
        {words.map((w, wi) => (
          <span key={wi}>
            <span style={{ display: "inline-block", whiteSpace: "nowrap" }}>
              {Array.from(w).map((ch, ci) => {
                const i = offsets[wi] + ci;
                const t = easings.out(progress(frame, 4 + i * 1.3, 16));
                return (
                  <span key={ci} style={{ display: "inline-block", opacity: t, transform: `translateY(${(1 - t) * 34}px)` }}>
                    {ch}
                  </span>
                );
              })}
            </span>
            {wi < words.length - 1 ? " " : null}
          </span>
        ))}
      </h1>
    );
  } else if (variant === "build") {
    body = (
      <h1 style={{ ...base, margin: 0, display: "flex", whiteSpace: "nowrap" }}>
        {words.map((w, i) => {
          const start = 6 + i * 9;
          const open = easings.out(progress(frame, start, 16));
          const pop = spring({ frame: frame - start, fps, config: springs.snappy });
          const estimate = (w.length + 1) * size * 0.62;
          return (
            <span key={i} style={{ display: "inline-block", overflow: "hidden", maxWidth: open >= 1 ? "none" : open * estimate, paddingBottom: size * 0.12 }}>
              <span
                style={{
                  display: "inline-block",
                  paddingRight: i < words.length - 1 ? "0.26em" : 0,
                  opacity: open,
                  transform: `scale(${interpolate(pop, [0, 1], [0.7, 1])})`,
                  transformOrigin: "50% 80%",
                  filter: `blur(${(1 - open) * 10}px)`,
                }}
              >
                {w}
              </span>
            </span>
          );
        })}
      </h1>
    );
  } else if (variant === "gather") {
    // Each word picks its own start, so the order is shuffled but repeatable.
    const order = words.map((_, i) => i).sort((a, b) => random(`order-${text}-${a}`) - random(`order-${text}-${b}`));
    body = (
      <h1 style={{ ...base, margin: 0, textAlign: "center", maxWidth: 1560, textWrap: "balance" }}>
        {words.map((w, i) => {
          const start = 2 + order.indexOf(i) * 5;
          const s = spring({ frame: frame - start, fps, config: springs.soft });
          const fx = (random(`x-${i}`) - 0.5) * 1500;
          const fy = (random(`y-${i}`) - 0.5) * 820;
          const rot = (random(`r-${i}`) - 0.5) * 50;
          const locked = progress(frame, start + 22, 10);
          return (
            <span key={i}>
              <span
                style={{
                  display: "inline-block",
                  opacity: interpolate(s, [0, 0.25], [0, 1], clamp),
                  filter: `blur(${(1 - s) * 14}px)`,
                  transform: `translate(${fx * (1 - s)}px, ${fy * (1 - s)}px) rotate(${rot * (1 - s)}deg) scale(${interpolate(s, [0, 1], [1.5, 1])})`,
                  position: "relative",
                }}
              >
                <span style={{ opacity: locked }}>{w}</span>
                <span style={{ position: "absolute", left: 0, top: 0, color: theme.primary, opacity: 1 - locked }}>{w}</span>
              </span>
              {i < words.length - 1 ? " " : null}
            </span>
          );
        })}
      </h1>
    );
  } else {
    body = (
      <h1 style={{ ...base, margin: 0, textAlign: "center", maxWidth: 1560, textWrap: "balance" }}>
        {words.map((w, i) => {
          const t = easings.out(progress(frame, 4 + i * 4.5, 24));
          return (
            <span key={i}>
              <span style={{ display: "inline-block", opacity: t, filter: `blur(${(1 - t) * 18}px)`, transform: `translateY(${(1 - t) * 56}px)` }}>{w}</span>
              {i < words.length - 1 ? " " : null}
            </span>
          );
        })}
      </h1>
    );
  }

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family, padding: 160 }}>
      {body}
    </AbsoluteFill>
  );
}
